function childrenFirst(root: TreeNode | null): number[] {
  const out: number[] = [];
  const walk = (node: TreeNode | null): void => {
    if (!node) return;
    walk(node.left);
    walk(node.right);
    out.push(node.val);
  };
  walk(root);
  return out;
}

