function childrenFirst(root: TreeNode | null): number[] {
  const out: number[] = [];
  const stack: TreeNode[] = [];
  let cur = root;
  let last: TreeNode | null = null;
  while (cur || stack.length) {
    while (cur) {
      stack.push(cur);
      cur = cur.left;
    }
    const top = stack[stack.length - 1];
    if (top.right && top.right !== last) {
      cur = top.right; // right subtree not done yet
    } else {
      out.push(top.val);
      last = stack.pop()!;
    }
  }
  return out;
}

